// Build the public URL list (newest first, capped at max_inspect_per_run).
const C = $('Config').first().json;
const wp = String(C.wp_site_url || '').replace(/\/+$/, '');
const pub = String(C.public_url_base || '').replace(/\/+$/, '');
const maxUrls = Number(C.max_inspect_per_run) || 200;
const key = String(C.indexnow_key || '').trim();

const all = [];
for (const it of $input.all()) {
  const j = it.json || {};
  const raw = j.link || '';
  if (!raw) continue;
  const publicUrl = (wp && pub && raw.indexOf(wp) === 0) ? pub + raw.substring(wp.length) : raw;
  const host = (publicUrl.match(/^https?:\/\/([^/?#]+)/i) || [])[1] || '';
  all.push({
    id: j.id,
    title: (j.title && (j.title.rendered || j.title)) || '',
    date: j.date || '',
    raw_url: raw,
    public_url: publicUrl,
    indexnow_host: host,
    indexnow_key_location: String(C.indexnow_key_location || '').trim() || (host && key ? `https://${host}/${key}.txt` : '')
  });
}

// Newest first
all.sort((a, b) => (b.date || '').localeCompare(a.date || ''));
return all.slice(0, maxUrls).map(item => ({ json: item }));

// Per URL: already indexed (PASS / PARTIAL) -> skip. Not indexed -> send to Google Indexing API (+ IndexNow).
// Inspection errors never trigger an indexing request.
const url = $('Loop Over URLs').item.json;
const r = $json;
let body = r.body;
if (typeof body === 'string') { try { body = JSON.parse(body); } catch (e) { /* keep string */ } }

if (r.error || !(r.statusCode >= 200 && r.statusCode < 300)) {
  const msg = r.error ? (typeof r.error === 'string' ? r.error : (r.error.message || JSON.stringify(r.error))) : 'Inspection API failed';
  return { json: { ...url, inspected: false, needs_indexing: false, error: msg, inspection_status: r.statusCode || null, inspection_detail: body || null } };
}

const idx = (body && body.inspectionResult && body.inspectionResult.indexStatusResult) || {};
const verdict = idx.verdict || 'UNKNOWN';
const isIndexed = verdict === 'PASS' || verdict === 'PARTIAL';
return { json: {
  ...url,
  inspected: true,
  is_indexed: isIndexed,
  needs_indexing: !isIndexed,
  verdict,
  coverage_state: idx.coverageState || '',
  last_crawl: idx.lastCrawlTime || null,
  action: isIndexed ? 'skipped_already_indexed' : 'to_index'
} };

