// Merge the Google Indexing API (and optional IndexNow) result into the URL record.
const base = $('Evaluate Inspection').item.json;
const g = $('Google Indexing API').item.json;
const googleOk = !g.error && g.statusCode >= 200 && g.statusCode < 300;
const indexnowOn = String($('Config').first().json.indexnow_key || '').trim() !== '';
let indexnowOk = null, indexnowStatus = null;
if (indexnowOn) {
  // When IndexNow is enabled this item comes from the IndexNow node.
  indexnowStatus = $json.statusCode || null;
  indexnowOk = !$json.error && ($json.statusCode === 200 || $json.statusCode === 202);
}
return { json: {
  ...base,
  action: 'indexed',
  google_ok: googleOk,
  google_status: g.statusCode || null,
  google_response: g.body || g.error || null,
  indexnow_ok: indexnowOk,
  indexnow_status: indexnowStatus
} };

// Aggregate all results for the report mail.
const items = $input.all().map(it => it.json);
const total = items.length;
const alreadyIndexed = items.filter(i => i.is_indexed === true).length;
const reIndexed = items.filter(i => i.action === 'indexed' && i.google_ok).length;
const indexFailed = items.filter(i => i.action === 'indexed' && !i.google_ok).length;
const inspectionFailed = items.filter(i => !i.inspected).length;

const failures = items
  .filter(i => !i.is_indexed && (i.error || i.google_ok === false))
  .slice(0, 30)
  .map(f => ({
    url: f.public_url,
    verdict: f.verdict || 'N/A',
    coverage: f.coverage_state || '',
    error: f.error || `Indexing HTTP ${f.google_status}`
  }));

const notIndexedSample = items
  .filter(i => i.is_indexed === false)
  .slice(0, 20)
  .map(f => ({
    url: f.public_url,
    verdict: f.verdict,
    coverage: f.coverage_state,
    action: f.action,
    google_ok: f.google_ok,
    indexnow_ok: f.indexnow_ok
  }));

return [{ json: {
  total,
  already_indexed: alreadyIndexed,
  re_indexed: reIndexed,
  index_failed: indexFailed,
  inspection_failed: inspectionFailed,
  failures,
  not_indexed_sample: notIndexedSample
} }];
